      },
      "after": {
        "requirement": "On failure to allocate the document URL base, expose XML_ERR_NO_MEMORY through the XInclude context.",
        "applicability": "required",
        "harness_status": "unknown",
        "reason": "The after path calls xmlRaiseMemoryError, whose implementation is absent. The supplied code does not establish whether it updates ctxt->errNo.",
